[
  {
    "alert_id": "P006_TDF_CREATININE_RISE",
    "title": "TDF-associated creatinine rise in pregnancy",
    "message": "Guidelines require serum creatinine and eGFR monitoring for patients initiating TDF. Creatinine rose from 0.8 to 1.1 mg/dL (eGFR 78) within 10 weeks of starting TDF, representing a ~38% eGFR decline from baseline. TDF is a known cause of renal toxicity including Fanconi syndrome and acute kidney injury. Pregnancy normally increases creatinine clearance, so a rising creatinine during pregnancy is particularly concerning. However, the urinalysis is normal without proteinuria, and phosphate remains normal, arguing against proximal tubular dysfunction. The eGFR decline approaches the 30% threshold for Grade 2 renal toxicity.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Repeat serum creatinine and eGFR promptly. If decline from baseline reaches 30% or more, consider TDF substitution to TAF and evaluate for Fanconi syndrome.",
    "citations": [
      {"page_number": 260, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"},
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 265, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p32_c1"}
    ]
  },
  {
    "alert_id": "P006_MONITORING_GAPS",
    "title": "Missing LFTs and no clinician plan documented",
    "message": "Guidelines recommend LFTs and RFTs when TDF toxicity signs arise, and viral load monitoring at 6 months after ART initiation then every 6–12 months. No liver function tests have been recorded despite 10 weeks on TDF/3TC/DTG. The clinician's assessment and plan are entirely blank, with no orders documented for ongoing renal monitoring, LFTs, or follow-up viral load scheduling. This represents both a monitoring gap and a plan deficiency for a pregnant patient on a regimen with known hepatorenal toxicities.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Document a plan including repeat creatinine/eGFR, LFTs, and schedule 6-month viral load. Address renal trend before it reaches the 30% decline threshold.",
    "citations": [
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 283, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p50_c2"},
      {"page_number": 260, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "P006_LOW_LEVEL_VIREMIA",
    "title": "Low-level viremia at 89 copies/mL on DTG",
    "message": "Guidelines recognize viral load above 200 copies/mL as associated with transmission risk and treatment failure. This patient's VL of 89 copies/mL is below that threshold but indicates incomplete suppression after 10 weeks. DTG-based regimens typically achieve rapid suppression. Low-level viremia may reflect early adherence challenges, baseline resistance, or pharmacokinetic variability in pregnancy. The viral load should be repeated per schedule at 6 months. If it rises above 200 copies/mL, enhanced adherence counseling and repeat testing are indicated.",
    "issue_type": "guideline_deviation",
    "severity": "low",
    "recommended_action": "Reinforce adherence counseling. Repeat viral load at 6-month mark per guideline schedule. If VL exceeds 200 copies/mL, provide intensive adherence counseling and repeat.",
    "citations": [
      {"page_number": 245, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p12_c2"},
      {"page_number": 283, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p50_c2"}
    ]
  }
]

